local SHAPES = { [0] = Enum.PartType.Ball, [1] = Enum.PartType.Block, [2] = Enum.PartType.Cylinder }

return function(name)
	local rows = DATA[name]
	if not rows then return nil end

	local model = Instance.new("Model")
	model.Name = name
	local groups = {}
	for _, row in ipairs(rows) do
		local shape = row[3]
		local part = Instance.new(shape == 9 and "WedgePart" or "Part")
		part.Name = row[2]
		if shape ~= 9 and SHAPES[shape] then part.Shape = SHAPES[shape] end
		part.Size = Vector3.new(row[4], row[5], row[6])
		part.CFrame = CFrame.new(row[7], row[8], row[9],
			row[10], row[11], row[12], row[13], row[14], row[15], row[16], row[17], row[18])
		part.Color = Color3.fromRGB(bit32.band(bit32.rshift(row[19], 16), 255),
			bit32.band(bit32.rshift(row[19], 8), 255), bit32.band(row[19], 255))
		local ok = pcall(function() part.Material = Enum.Material[row[20]] end)
		if not ok then part.Material = Enum.Material.Plastic end
		part.Transparency = row[21]
		part.Reflectance = row[22]
		part.CanCollide = row[23] == 1
		part.Anchored = true

		local group = row[1]
		if group == "" then
			part.Parent = model
		else
			local holder = groups[group]
			if not holder then
				holder = Instance.new("Model")
				holder.Name = group
				holder.Parent = model
				groups[group] = holder
			end
			part.Parent = holder
		end
	end

	local root = model:FindFirstChild("Root")
	if root then model.PrimaryPart = root end
	return model
end
